INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000001', 'ORD-20251016-206449', 'CUST-10417', 'REST-AUH-002', 'Poor experience. Dal Makhani and Chole Bhature were disappointing. Dal Makhani was burnt on the edges. Very unhappy.', 2, '2025-10-20T12:36:54.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000002', 'ORD-20251018-240725', 'CUST-10290', 'REST-DXB-002', 'Pleasant meal! Samosa (2 pcs)  Gulab Jamun (2 pcs)  Jeera Rice  and Paneer Tikka arrived warm. Samosa (2 pcs) was tasty though not exceptional. Would order again.', 4, '2025-10-23T20:07:50.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000004', 'ORD-20251029-283129', 'CUST-10106', 'REST-DXB-002', 'Perfect in every way! Garlic Naan  Chicken 65  Lamb Rogan Josh  and Kulfi were all excellent. Chicken 65 stood out with its rich  authentic taste.', 5, '2025-11-01T13:00:39.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000003', 'ORD-20251025-537536', 'CUST-10440', 'REST-AUH-002', 'Enjoyed the Chicken Biryani and Garlic Naan! Garlic Naan was very good. Portion sizes were generous. Recommend!', 4, '2025-11-01T21:48:42.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000006', 'ORD-20251104-580819', 'CUST-10270', 'REST-DXB-001', 'Perfect in every way! Chicken Seekh Kebab and Chicken Tikka Masala were all excellent. Chicken Tikka Masala stood out with its rich  authentic taste.', 5, '2025-11-05T12:54:04.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000005', 'ORD-20251101-126822', 'CUST-10226', 'REST-SHJ-001', 'Decent food but nothing special. Fresh Lime Soda  Chole Bhature  Paneer Tikka  and Gulab Jamun (2 pcs) were okay. Chole Bhature lacked the punch I expected.', 3, '2025-11-05T16:24:35.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000007', 'ORD-20251116-896829', 'CUST-10328', 'REST-DXB-001', 'Solid experience. Chicken Tikka Masala  Chicken Biryani  Dal Makhani  Fish Curry  and Masala Chai were well-prepared. Fish Curry had great flavor. Minor issues with packaging.', 4, '2025-11-23T11:08:20.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000010', 'ORD-20251127-953251', 'CUST-10220', 'REST-DXB-001', 'Very satisfied! Gajar Halwa  Chole Bhature  Tandoori Roti  and Butter Naan were fresh and flavorful. Tandoori Roti was the standout dish.', 4, '2025-11-28T22:26:38.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000009', 'ORD-20251127-397094', 'CUST-10413', 'REST-DXB-002', 'Good quality food. Paneer Tikka and Gajar Halwa were nicely done. Gajar Halwa could have been slightly spicier but still good!', 4, '2025-11-30T19:02:26.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000011', 'ORD-20251128-782125', 'CUST-10469', 'REST-SHJ-001', 'Very satisfied! Chole Bhature and Malai Kofta were fresh and flavorful. Chole Bhature was the standout dish.', 4, '2025-12-02T10:26:50.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000008', 'ORD-20251126-872339', 'CUST-10038', 'REST-AUH-001', 'Average experience. Paneer Butter Masala  Samosa (2 pcs)  and Chicken Biryani were fine but Samosa (2 pcs) was a bit bland. Room for improvement.', 3, '2025-12-03T19:47:34.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000012', 'ORD-20251206-619550', 'CUST-10191', 'REST-AUH-001', 'Absolutely amazing Palak Paneer  Mango Lassi  and Naan! The Naan was cooked to perfection. Fresh ingredients and authentic flavors. Highly recommend!', 5, '2025-12-12T10:59:50.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000014', 'ORD-20251211-760415', 'CUST-10352', 'REST-DXB-002', 'Hands down the best Chicken 65 I''ve ever had! Chicken 65 were all prepared beautifully. Fresh and flavorful!', 5, '2025-12-14T18:55:09.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000013', 'ORD-20251209-112325', 'CUST-10254', 'REST-SHJ-001', 'Absolutely amazing Chicken 65! The Chicken 65 was cooked to perfection. Fresh ingredients and authentic flavors. Highly recommend!', 5, '2025-12-15T20:08:17.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000015', 'ORD-20251212-267721', 'CUST-10177', 'REST-DXB-001', 'Great food overall. Dal Makhani  Kulfi  and Gulab Jamun (2 pcs) were tasty  especially the Gulab Jamun (2 pcs). Would order again!', 4, '2025-12-16T15:07:45.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000016', 'ORD-20251214-932936', 'CUST-10191', 'REST-AUH-002', 'Wow! Just wow! Palak Paneer  Tandoori Roti  Naan  and Lamb Rogan Josh were all fantastic. Tandoori Roti was particularly memorable. Can''t wait to order again!', 5, '2025-12-17T13:39:40.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000018', 'ORD-20251217-850672', 'CUST-10373', 'REST-DXB-002', 'Perfect in every way! Chicken Seekh Kebab were all excellent. Chicken Seekh Kebab stood out with its rich  authentic taste.', 5, '2025-12-18T18:34:17.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000017', 'ORD-20251216-603542', 'CUST-10025', 'REST-AUH-001', 'Exceptional quality! Ordered Chicken Biryani and everything was delicious. The Chicken Biryani melted in my mouth. Perfect!', 5, '2025-12-21T18:23:55.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000019', 'ORD-20251226-906568', 'CUST-10068', 'REST-DXB-001', 'Absolutely amazing Kulfi  Lamb Rogan Josh  and Palak Paneer! The Lamb Rogan Josh was cooked to perfection. Fresh ingredients and authentic flavors. Highly recommend!', 5, '2025-12-30T12:19:52.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000020', 'ORD-20251230-468462', 'CUST-10475', 'REST-SHJ-001', 'Pleasant meal! Kulfi and Vegetable Biryani arrived warm. Kulfi was tasty though not exceptional. Would order again.', 4, '2026-01-01T14:01:06.076024');
INSERT INTO customer_reviews (review_id, order_id, customer_id, restaurant_id, review_text, rating, review_timestamp) VALUES ('REV-000022', 'ORD-20260101-819358', 'CUST-10365', 'REST-SHJ-001', 'Great food overall. Tandoori Roti  Rasmalai (2 pcs)  Chicken Tikka Masala  and Gajar Halwa were tasty  especially the Tandoori Roti. Would order again!', 4, '2026-01-02T12:39:55.076024');
